import java.util.Scanner;

public class Main {
    public static int countDigitsOf(long n) {
        int count = 0;
        while (n != 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    public static long largestRepeatingOnes(long n) {
        int length = countDigitsOf(n);
        long total = 0, base = 1;
        for (int i = 0; i < length; i++) {
            total += base;
            base *= 10;
        }
        if (total <= n) return total;
        return (total - 1) / 10;
    }

    public static long solveNumber(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base = largestRepeatingOnes(n);
        long nextValue = base * 10 + 1;
        if (n % base == 0) {
            if (n <= (nextValue / 2 + base))
                return countDigitsOf(base) * n / base;
            return countDigitsOf(nextValue) + solveNumber(nextValue - n);
        } else {
            long m = (n / base) * base;
            long res = solveNumber(m) + solveNumber(n - m);
            if (n > nextValue / 2)
                res = Math.min(solveNumber(m) + solveNumber(n - m), countDigitsOf(nextValue) + solveNumber(nextValue - n));
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(solveNumber(n));
        scanner.close();
    }
}
